// milFilter.js — filtre « Attaques militaires » (conflict_typology === 'MIL').
//
// S'applique APRÈS buildEnrichedTweets / filterTweets : la copie garde toutes les
// métadonnées de la collection (availableLabels..., compteurs...), seules les
// features sont filtrées. Si `enabled` est faux, la collection est renvoyée telle quelle.
//
// keepUntyped : pour les lignes militaires (flèches agresseur -> cible), qui sont par
// nature militaires ; on ne retire qu'une ligne explicitement typée autrement que MIL.
export function keepMilOnly(fc, enabled, { keepUntyped = false } = {}) {
    if (!enabled || !fc?.features) return fc;
    return {
        ...fc,
        features: fc.features.filter((f) => {
            const typology = f.properties?.conflict_typology;
            return typology === "MIL" || (keepUntyped && typology == null);
        }),
    };
}