import { useState, useEffect, useRef } from "react";
import { IoCheckmark } from "react-icons/io5";

// Menu déroulant unique du SidePanel (période, sujets...) : un déclencheur « pastille »
// + un menu flottant à choix unique (coche sur l'élément actif).
//
//   items       : [{ key, label }]
//   selectedKey : clé de l'élément coché
//   onSelect    : (key) => void  (le menu se referme ensuite)
//   label       : texte affiché sur le déclencheur
//   grow        : le déclencheur occupe toute la largeur disponible
//   scroll      : menu à hauteur limitée, avec défilement (longues listes)
//   active      : met le déclencheur en évidence (un filtre est appliqué)
//
// Clavier : Échap ferme et rend le focus au déclencheur ; flèches haut / bas déplacent le
// focus ; clic en dehors ferme. À l'ouverture, le focus va sur l'élément coché.
export default function Dropdown({
    items, selectedKey, onSelect, label, ariaLabel,
    disabled = false, active = false, grow = false, scroll = false,
}) {
    const [open, setOpen] = useState(false);
    const rootRef = useRef(null);

    useEffect(() => {
        if (!open) return;
        const root = rootRef.current;
        (root?.querySelector('[aria-checked="true"]') ?? root?.querySelector('[role="menuitemradio"]'))?.focus();
        const onPointerDown = (e) => { if (!root?.contains(e.target)) setOpen(false); };
        const onKey = (e) => {
            if (e.key === "Escape") { setOpen(false); root?.querySelector(".sp-pill")?.focus(); }
        };
        document.addEventListener("pointerdown", onPointerDown);
        document.addEventListener("keydown", onKey);
        return () => {
            document.removeEventListener("pointerdown", onPointerDown);
            document.removeEventListener("keydown", onKey);
        };
    }, [open]);

    const onMenuKeyDown = (e) => {
        if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
        e.preventDefault();
        const els = Array.from(rootRef.current.querySelectorAll('[role="menuitemradio"]'));
        const i = els.indexOf(document.activeElement);
        const next = e.key === "ArrowDown" ? (i + 1) % els.length : (i - 1 + els.length) % els.length;
        els[next]?.focus();
    };

    return (
        <div className={`sp-dd${grow ? " sp-dd--grow" : ""}`} ref={rootRef}>
            <button
                type="button"
                className={`sp-pill${open ? " sp-pill--open" : ""}${active ? " sp-pill--active" : ""}`}
                onClick={() => setOpen((o) => !o)}
                disabled={disabled}
                aria-haspopup="menu"
                aria-expanded={open}
                aria-label={ariaLabel}
            >
                <span className="sp-pill-text">{label}</span>
                <svg className="sp-pill-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                    <path d="m6 9 6 6 6-6" />
                </svg>
            </button>
            {open && (
                <div
                    className={`sp-dd-menu${scroll ? " sp-dd-menu--scroll" : ""}`}
                    role="menu"
                    aria-label={ariaLabel}
                    onKeyDown={onMenuKeyDown}
                >
                    {items.map((item) => (
                        <button
                            key={item.key}
                            type="button"
                            role="menuitemradio"
                            aria-checked={selectedKey === item.key}
                            className="sp-dd-item"
                            onClick={() => { onSelect(item.key); setOpen(false); }}
                        >
                            <span>{item.label}</span>
                            {selectedKey === item.key && <IoCheckmark size={16} aria-hidden="true" />}
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
}